/bin/bash -lc "time samtools view -@ 4 pooled.infer.donors.q1.bam | perl -ne '
while(/\\t(CB|CR|BC):Z:(["'^'"\\t]+)/g){ "'$tag{$1}{$2}++ }
END{
 for $t (sort keys %tag){ print "$t unique=", scalar(keys %{$tag{$t}}), "'"\\n\"; for "'$k (sort {$tag{$t}{$b}<=>$tag{$t}{$a}} keys %{$tag{$t}}){ print "$t'"\\t"'$k'"\\t"'$tag{$t}{$k}'"\\n\"; } }
}' > tag_counts.txt
wc -l tag_counts.txt
head -100 tag_counts.txt
"

