/bin/bash -lc "time samtools view -@ 4 pooled.infer.donors.q1.bam | perl -ne '
if(/\\tCB:Z:(["'^'"\\t]+)/){"'$cb=$1} if(/'"\\tBC:Z:(["'^'"\\t]+)/){"'$bc=$1} if(defined $cb && defined $bc){$cellbc{$cb}{$bc}++} 
END{
 for $c (sort keys %cellbc){$n=keys %{$cellbc{$c}}; $nc{$n}++; if($n>1){print "MULTI'"\\t"'$c'"\\t\", join(\",\",map{\""'$_:".$cellbc{$c}{$_}} keys %{$cellbc{$c}}),"'"\\n\";}}
 print \"cells_with_n_BC:\\n\"; for "'$n (sort keys %nc){print "$n'"\\t"'$nc{$n}'"\\n\";}
}' > cell_bc_map.txt
cat cell_bc_map.txt | head -50"

